local function get_table_ids( tblsrc, tbldst )
	local nCount = 0
	for k,v in pairs(tblsrc) do
		nCount = nCount+1
		tbldst[nCount] = k
	end
	tbldst[nCount+1] = nCount
end

-- for gs
function find_common_inst( inst_id, key )
	ret = ""
	if InstInfo_Common[inst_id] ~= nil and InstInfo_Common[inst_id][key] ~= nil then
		ret = InstInfo_Common[inst_id][key]
	end
	return ret
end
function get_common_inst_list()
	idtab = {}
	get_table_ids(InstInfo_Common,idtab)
	return idtab
end
-- for client --
function get_common_inst()
	return InstInfo_Common
end
-- for deliver
function get_team_kickout_need_vote_list()
	idtab = {}
	local nCount = 0
	for k,v in pairs(InstInfo_Common) do
		nv = v["team_kickout_need_vote"]
		if nv and nv>0 then
			nCount = nCount+1
			idtab[nCount] = k
		end
	end
	return nCount, unpack(idtab)
end
